<script setup>
import {computed,ref} from 'vue'
import {api} from './api'
const props=defineProps({token:String,language:String,configuration:Object,canApply:Boolean,idle:Boolean})
const emit=defineEmits(['saved'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const selected=ref(''),busy=ref(false),error=ref(''),notice=ref(''),confirming=ref(false)
const current=computed(()=>{const a=props.configuration?.inputs;return a?.length===8&&a.every(i=>i.active_low===a[0].active_low)?String(a[0].active_low):''})
const label=value=>value==='true'?tr('Старая плата: нажатие = 0','Eski plata: bosilganda = 0','Old board: pressed = 0'):value==='false'?tr('Новая плата IN / GND_IN: нажатие = 1','Yangi IN / GND_IN plata: bosilganda = 1','New IN / GND_IN board: pressed = 1'):tr('Разные уровни / нет данных','Turli darajalar / ma’lumot yo‘q','Mixed levels / no data')
async function save(){if(busy.value||!props.canApply)return;busy.value=true;error.value='';notice.value='';try{await api('/api/admin/service/input-polarity',{token:props.token,method:'POST',body:JSON.stringify({active_low:selected.value==='true'})});notice.value=tr('Сохранено. Отпущенные кнопки должны показывать «Неактивен». Выберите программу заново.','Saqlandi. Qo‘yib yuborilgan tugmalar «Faol emas» bo‘lishi kerak. Dasturni qayta tanlang.','Saved. Released buttons must show inactive. Select the program again.');selected.value='';emit('saved')}catch(e){error.value=e.message}finally{busy.value=false;confirming.value=false}}
</script>
<template><section class="card content"><h2>{{tr('Тип входов I/O-платы','I/O plata kirish turi','I/O input type')}}</h2><p>{{tr('Меняет полярность всех восьми входов IN1–IN8. Купюроприёмник и зависимость от курка не меняются.','IN1–IN8 kirish qutbliligini o‘zgartiradi. Banknota qabul qilgich va tepki talabi o‘zgarmaydi.','Changes all eight IN1–IN8 polarities. Bill acceptor and trigger requirement stay unchanged.')}}</p><p>{{tr('Сейчас','Hozir','Current')}}: {{label(current)}}</p><label>{{tr('Выберите тип входов','Kirish turini tanlang','Select input type')}}<select v-model="selected" :disabled="busy" @change="confirming=false;notice=''" ><option value="" disabled>—</option><option value="true">{{label('true')}} (active_low: true)</option><option value="false">{{label('false')}} (active_low: false)</option></select></label><p class="muted">{{tr('Свободный вход старой платы: raw = 1; новой: raw = 0. Проверьте документацию I/O-платы и таблицу входов.','Eski plataning bo‘sh kirishi: raw = 1; yangisi: raw = 0. Plata hujjati va kirish jadvalini tekshiring.','Idle input: old board raw = 1; new board raw = 0. Check your board manual and the input table.')}}</p><p v-if="!idle" class="muted">{{tr('Сначала завершите сеанс и сохраните остаток клиента.','Avval seansni yakunlab, mijoz qoldig‘ini saqlang.','Finish the session and preserve customer credit first.')}}</p><div v-if="error" class="message error">{{error}}</div><div v-if="notice" class="message success">{{notice}}</div><template v-if="confirming"><p>{{tr('Применить ко всем восьми входам?','Sakkiz kirishga qo‘llansinmi?','Apply to all eight inputs?')}} {{label(selected)}}</p><button class="primary" :disabled="busy||!canApply" @click="save">{{tr('Подтвердить','Tasdiqlash','Confirm')}}</button> <button class="quiet" :disabled="busy" @click="confirming=false">{{tr('Отмена','Bekor qilish','Cancel')}}</button></template><button v-else class="primary" :disabled="busy||!canApply||!selected||selected===current" @click="confirming=true">{{tr('Применить тип входов','Kirish turini qo‘llash','Apply input type')}}</button></section></template>
